using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
using Object=UnityEngine.Object;

// Export only missing profiles. Existing designer edits are never regenerated by this command.
public static class BalanceAssetBuilder
{
    const string Root="Assets/Projects/Resources/Balance/";
    [Serializable] sealed class Constant { public string Type="",Key="",Label="",Source="";public float Value=0; }
    [Serializable] sealed class Constants {public Constant[] items=Array.Empty<Constant>();}
    static Constant[] constants;
    static readonly Dictionary<string,string> routes=new();
    static readonly Dictionary<Object,Object> effectCopies=new();
    static readonly HashSet<string> excluded=new(){"curBlood","curAngry","currentMana","currentVigor","experience","boostEnergy","attackedUp","Attacked","Comboed","Skilled","SkillThreeCur","AttackThisFrame","LandedThisFrame","JumpedThisFrame","AngryRequest","AttackFaceRight","curWave","waveStartTime","playerInNextWave","isBoss","playerId"};
    static readonly Dictionary<string,string> labels=new()
    {
        ["beginBlood"]="基础生命上限",["experienceReward"]="击杀经验",["Attack"]="基础伤害",["moveSpeed"]="移动速度",["walkSpeed"]="走路速度",["runSpeed"]="跑步速度",["upSpeed"]="跳跃速度",["backSpeed"]="受击后退速度",["attackDelay"]="攻击冷却/间隔",["cooldowns"]="各技能冷却（秒）",["skillCooldowns"]="各技能冷却（秒）",["maxMana"]="最大法力",["maxVigor"]="最大气力",["deltaBoost"]="每次有效命中增加无双",["boostFull"]="无双能量上限",["boostTime"]="无双持续秒数",["boostReduce"]="无双能量每秒衰减",["manaCost"]="法力消耗",["cooldown"]="冷却秒数",["vigorCost"]="气力消耗",["vigorPerSecond"]="持续气力消耗/秒",["criticalChance"]="暴击概率",["criticalMultiplier"]="暴击倍率",["stopDistance"]="停止靠近距离",["damage"]="伤害",["duration"]="持续时间",["lifetime"]="存在时间",["radius"]="作用半径",["attackInterval"]="普通招式间隔",["releaseFrames"]="释放帧",["windups"]="前摇秒数",["AttackOpenIdx"]="开箱帧索引",["AttackShutIdx"]="关箱帧索引",["dropChance"]="金币掉落概率",["bossGold"]="Boss首杀金币",["maxGold"]="小怪金币上限",["runVigorPerSecond"]="奔跑气力/秒",["jumpVigorCost"]="跳跃气力",["idleVigorRecovery"]="静止气力恢复/秒",["attackedVigorRecovery"]="受击气力恢复/秒"
    };
    static string Label(string path)
    {
        string field=path.Split('.')[0];return (labels.TryGetValue(field,out var label)?label:field)+" · "+path;
    }
    static BalanceProfile Profile(string route,string title)
    {
        string path=Root+route+".asset";var asset=AssetDatabase.LoadAssetAtPath<BalanceProfile>(path);
        if(asset!=null)return asset;
        Directory.CreateDirectory(Path.GetDirectoryName(path));AssetDatabase.Refresh();
        asset=ScriptableObject.CreateInstance<BalanceProfile>();asset.displayName=title;
        AssetDatabase.CreateAsset(asset,path);return asset;
    }
    static string Owner(string type,string source)
    {
        foreach(string player in new[]{"Wukong","Bajie","Tang","Sha"})if(source.Contains("/Player/"+player+"/"))return "Players/"+player;
        string[] actors={"Wolf","Tiger","PurpleHeavenly","PurpleRanged","BlueShield","BlueWheel","RedChain","RedBoom","GreenHammer","GreenSummon","RollingFurnace","ClampGuard","PressureKettle","StarShearGuard","ConstellationWeaver","ResonantStarOwl","RiftBlade","SealWarden","PhaseWeaver"};
        foreach(string actor in actors)if(source.Contains("/Enemy/"+actor+"/"))return "Enemies/"+(actor=="Wolf"?"WolfEnemy":actor=="Tiger"?"TigerEnemy":actor);
        string[] bosses={"Titan","EastKing","SouthKing","WestKing","NorthKing","RedFurnaceLord","JiuyaoXuanhuang","WuxiangDijun"};
        foreach(string actor in bosses)if(source.Contains("/Boss/"+actor+"/"))return "Bosses/"+(actor=="Titan"?"TitanSpirit":actor);
        return "Common/CombatRules";
    }
    public static void Build()
    {
        foreach(string name in new[]{"SouthKingMeleeFreeze","SouthKingGuaranteedFreeze"})
        {
            var original=AssetDatabase.LoadAssetAtPath<AttackEffect>("Assets/Projects/Scripts/Boss/SouthKing/"+name+".asset");
            string path=Root+"StatusEffects/"+name+".asset";Directory.CreateDirectory(Path.GetDirectoryName(path));AssetDatabase.Refresh();
            var copy=AssetDatabase.LoadAssetAtPath<AttackEffect>(path);if(copy==null){copy=Object.Instantiate(original);AssetDatabase.CreateAsset(copy,path);}effectCopies[original]=copy;
        }
        constants=JsonUtility.FromJson<Constants>("{\"items\":"+File.ReadAllText("Assets/Projects/Editor/Data/BalanceMigrationManifest.json")+"}").items;
        foreach(var c in constants)routes[c.Type]=Owner(c.Type,c.Source);
        var shared=Profile("Common/CombatRules","公共战斗与控制规则");
        if(shared.numbers.Length==0){shared.numbers=constants.Where(c=>Owner(c.Type,c.Source)=="Common/CombatRules").Select(Convert).ToArray();EditorUtility.SetDirty(shared);}
        foreach(string folder in new[]{"Character","Enemy","SeparateEffort"})
            foreach(string file in Directory.GetFiles("Assets/Projects/Prefabs/"+folder,"*.prefab"))
            {
                string name=Path.GetFileNameWithoutExtension(file);
                string category=folder=="Character"?"Players":folder=="Enemy"?(new[]{"TitanSpirit","EastKing","SouthKing","WestKing","NorthKing","RedFurnaceLord","JiuyaoXuanhuang","WuxiangDijun"}.Contains(name)?"Bosses":"Enemies"):"Effects";
                string id=name=="WuKong"?"Wukong":name;Export(file,category+"/"+id,name);
            }
        Export("Assets/Projects/Prefabs/Level/PlayerSystem.prefab","Common/PartyAndGold","换人、金币与团队规则");
        Export("Assets/Projects/Resources/Gold/Coin.prefab","Common/GoldCoin","金币拾取与寿命");
        var legacy=Resources.Load<SkillProgression>("Skills/SkillProgression");
        var data=new SerializedObject(legacy).FindProperty("skills");
        foreach(PlayerId id in Enum.GetValues(typeof(PlayerId)))
        {
            var profile=BalanceRuntime.Player(id);
            if(profile==null)throw new Exception("Player profile missing "+id);
            if(profile.skills.Length!=0)continue;
            var defs=new List<SkillProgression.SkillDefinition>();
            for(int i=0;i<data.arraySize;i++)
            {
                var s=data.GetArrayElementAtIndex(i);if(s.FindPropertyRelative("player").intValue!=(int)id)continue;
                var levels=s.FindPropertyRelative("levels");var values=new SkillLevelData[levels.arraySize];
                for(int j=0;j<values.Length;j++){var v=levels.GetArrayElementAtIndex(j);values[j]=new SkillLevelData(v.FindPropertyRelative("goldCost").intValue,v.FindPropertyRelative("manaCost").intValue,v.FindPropertyRelative("cooldown").intValue);}
                defs.Add(new SkillProgression.SkillDefinition{player=id,skillNumber=s.FindPropertyRelative("skillNumber").intValue,levels=values});
            }
            profile.skills=defs.ToArray();EditorUtility.SetDirty(profile);
        }
        foreach(var group in constants.GroupBy(c=>Owner(c.Type,c.Source)))
        {
            var profile=Profile(group.Key,group.Key.Split('/').Last());
            var keys=new HashSet<string>(profile.numbers.Select(n=>n.key));
            profile.numbers=profile.numbers.Concat(group.Where(c=>!keys.Contains(c.Key)).Select(Convert)).ToArray();EditorUtility.SetDirty(profile);
        }
        var progression=Profile("Common/Progression","技能等级规则");
        if(progression.numbers.Length==0){progression.numbers=new[]{new BalanceProfile.Number{key="Skills.MaxLevel",label="技能最高等级",value=legacy.MaxLevel}};EditorUtility.SetDirty(progression);}
        var rebirth=Profile("Common/Rebirth","轮回难度倍率");
        if(rebirth.numbers.Length==0)
        {
            rebirth.numbers=new[]{Rule("Cap","数值增长封顶轮数",10),Rule("HPPerRound","每轮生命增长",.35f),Rule("DamagePerRound","每轮伤害增长",.15f),Rule("GoldPerRound","每轮金币增长",.25f),Rule("ExperiencePerRound","每轮经验增长",.2f),Rule("QuantityPerRound","每轮数量增长",.08f),Rule("MinimumAttackCooldown","攻击冷却最低倍率",.75f),Rule("AttackCooldownPerRound","每轮攻击冷却减少",.03f),Rule("MovementPerRound","每轮移速增长",.02f),Rule("MinimumSpawnDelay","刷怪间隔最低倍率",.7f),Rule("SpawnDelayPerRound","每轮刷怪间隔减少",.03f),Rule("AlivePerRound","每轮同屏上限增长",.1f),Rule("MaximumExtraAlive","同屏上限最多增加",1)};
            EditorUtility.SetDirty(rebirth);
        }
        File.WriteAllLines(Root+"TypeRoutes.txt",routes.OrderBy(p=>p.Key).Select(p=>p.Key+"|"+p.Value));
        AssetDatabase.SaveAssets();AssetDatabase.Refresh();
        BuildLevelProfiles();
        Directory.CreateDirectory("output/BalanceAudit");File.WriteAllText("output/BalanceAudit/assets-built.txt","PASS assets and prefab bindings exported\n");
    }
    static BalanceProfile.Number Convert(Constant c)=>new(){key=c.Key,label=c.Label,source=c.Source,value=c.Value};
    static BalanceProfile.Number Rule(string key,string label,float value)=>new(){key=key,label=label,value=value};
    static bool ValidParameter(string typeName,string path)
    {
        if(path.Contains(".m_")||excluded.Contains(path.Split('.')[0]))return false;
        Type type=BalanceBinding.ResolveType(typeName);if(type==typeof(Rigidbody2D))return true;if(BalanceBinding.ControlsSize(type))return false;//碰撞箱、缩放只由预制体控制
        foreach(var token in path.Replace(".Array.data[","[").Split('.'))
        {
            string field=token.Split('[')[0];System.Reflection.FieldInfo member=null;
            for(Type t=type;t!=null&&member==null;t=t.BaseType)member=t.GetField(field,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.DeclaredOnly);
            if(member==null)return false;type=member.FieldType;
            if(token.Contains("[")){if(!type.IsArray)return false;type=type.GetElementType();}
            if(typeof(Object).IsAssignableFrom(type)||type==typeof(string))return false;
        }
        return type==typeof(float)||type==typeof(int)||type==typeof(double)||type==typeof(bool);
    }
    static void BuildLevelProfiles()
    {
            for(int level=1;level<=9;level++)
            {
                var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenPreviewScene($"Assets/Projects/Scenes/Levels/Level{level}Scene.unity");
                try
                {
                var profile=Profile("Levels/Level"+level+"Scene","第"+level+"关刷怪与召唤参数");
                var groups=new List<BalanceProfile.ComponentSettings>();
                foreach(var component in scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<Component>(true)).Where(c=>c is LevelManager||c is StageEnemyManager))
                {
                    var so=new SerializedObject(component);var values=new List<BalanceProfile.Parameter>();
                    foreach(string field in new[]{"leftEnemyMax","rightEnemyMax","enemyDelay","enemyMax","firstEnemyDelay","bossBornDelay","maxSummonedEnemies","summonedHpScale","summonedDamageScale"})
                    {
                        var p=so.FindProperty(field);if(p==null)continue;
                        if(p.isArray)for(int i=0;i<p.arraySize;i++)values.Add(new BalanceProfile.Parameter{path=field+".Array.data["+i+"]",label=field+" 第"+(i+1)+"波",integer=true,value=p.GetArrayElementAtIndex(i).intValue});
                        else values.Add(new BalanceProfile.Parameter{path=field,label=Label(field),integer=p.propertyType==SerializedPropertyType.Integer,value=p.propertyType==SerializedPropertyType.Integer?p.intValue:p.doubleValue});
                    }
                    var pools=so.FindProperty("enemyPools");
                    if(pools!=null)for(int i=0;i<pools.arraySize;i++)foreach(string field in new[]{"poolSize","weight"})
                    {
                        var value=pools.GetArrayElementAtIndex(i).FindPropertyRelative(field);
                        values.Add(new BalanceProfile.Parameter{path="enemyPools.Array.data["+i+"]."+field,label="第"+(i+1)+"种敌人 / "+(field=="weight"?"生成权重":"预热数量"),integer=field=="poolSize",value=field=="poolSize"?value.intValue:value.doubleValue});
                    }
                    if(values.Count>0)groups.Add(new BalanceProfile.ComponentSettings{componentType=component.GetType().FullName,parameters=values.ToArray()});
                }
                var existing=profile.components.ToList();
                foreach(var group in groups){var old=existing.FirstOrDefault(g=>g.componentType==group.componentType);if(old==null)existing.Add(group);else{var keys=new HashSet<string>(old.parameters.Select(p=>p.path));old.parameters=old.parameters.Concat(group.parameters.Where(p=>!keys.Contains(p.path))).ToArray();}}
                profile.components=existing.ToArray();EditorUtility.SetDirty(profile);
                }
                finally{UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(scene);}
            }
            AssetDatabase.SaveAssets();
    }
    [MenuItem("Tools/数值配置/补齐缺少的数据资产（保留已有调参）")]
    public static void FinalizeMetadata()
    {
        Build();
        var all=AssetDatabase.FindAssets("t:BalanceProfile",new[]{Root.TrimEnd('/')}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<BalanceProfile>).ToArray();
        var labels=constants.ToDictionary(c=>c.Key,c=>c);
        foreach(var profile in all)
        {
            foreach(var group in profile.components)group.parameters=group.parameters.Where(p=>ValidParameter(group.componentType,p.path)).ToArray();
            foreach(var n in profile.numbers)if(labels.TryGetValue(n.key,out var info)){n.label=info.Label;n.source=info.Source;}
            foreach(var group in profile.components)
                if(group.componentType==typeof(PlayerCombat).FullName||typeof(PlayerCombat).IsAssignableFrom(typeof(PlayerCombat).Assembly.GetType(group.componentType)))
                    group.parameters=group.parameters.Where(p=>!p.path.EndsWith(".manaCost")&&!p.path.EndsWith(".cooldown")).ToArray();
            profile.components=profile.components.Where(g=>g.parameters.Length>0).ToArray();
            string name=Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(profile));
            var titles=new Dictionary<string,string>{{"Wukong","孙悟空"},{"Bajie","猪八戒"},{"Tang","唐僧"},{"Sha","沙僧"},{"RedChain","赤链武卒"},{"RedBoom","引魂灯使"},{"GreenHammer","青玉锤卒"},{"GreenSummon","青幡令使"},{"WestKing","广目天王"},{"NorthKing","多闻天王"},{"EastKing","持国天王"},{"SouthKing","增长天王"},{"JiuyaoXuanhuang","九曜玄凰"},{"WuxiangDijun","无相帝君"},{"RiftBlade","裂隙刃侍"},{"SealWarden","缄印镇卫"},{"PhaseWeaver","倒相织使"}};
            if(titles.TryGetValue(name,out var title)&&(profile.displayName==name||profile.displayName=="WuKong"))profile.displayName=title+" / "+name;
            if(!AssetDatabase.GetAssetPath(profile).Contains("/Effects/"))
                profile.relatedProfiles=all.Where(p=>AssetDatabase.GetAssetPath(p).Contains("/Effects/")&&(p.name.StartsWith(name,StringComparison.Ordinal)||p.components.Any(g=>routes.TryGetValue(g.componentType,out var owner)&&Root+owner+".asset"==AssetDatabase.GetAssetPath(profile)))).ToArray();
            profile.Invalidate();EditorUtility.SetDirty(profile);
        }
        AssetDatabase.SaveAssets();
        string catalogPath=Root+"BalanceCatalog.asset";var catalog=AssetDatabase.LoadAssetAtPath<BalanceCatalog>(catalogPath);
        if(catalog==null){catalog=ScriptableObject.CreateInstance<BalanceCatalog>();AssetDatabase.CreateAsset(catalog,catalogPath);}
        BalanceProfile[] Category(string name)=>all.Where(p=>AssetDatabase.GetAssetPath(p).Contains("/Balance/"+name+"/")).OrderBy(p=>p.name).ToArray();
        catalog.players=Category("Players");catalog.enemies=Category("Enemies");catalog.bosses=Category("Bosses");catalog.effects=Category("Effects");catalog.common=Category("Common");catalog.levels=Category("Levels");EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();
    }
    static void Export(string path,string route,string title)
    {
        var asset=Profile(route,title);var prefab=PrefabUtility.LoadPrefabContents(path);
        try
        {
            if(path.Contains("/Prefabs/Enemy/")&&prefab.GetComponent<EnemyRewards>()==null)prefab.AddComponent<EnemyRewards>();
            var settings=new List<BalanceProfile.ComponentSettings>();
            foreach(var component in prefab.GetComponentsInChildren<MonoBehaviour>(true))
            {
                if(component==null||component is BalanceBinding||component.GetType().Assembly!=typeof(Health).Assembly)continue;
                var references=new SerializedObject(component);var reference=references.GetIterator();
                while(reference.Next(true))if(reference.propertyType==SerializedPropertyType.ObjectReference&&reference.objectReferenceValue!=null&&effectCopies.TryGetValue(reference.objectReferenceValue,out var effect))reference.objectReferenceValue=effect;
                references.ApplyModifiedPropertiesWithoutUndo();
                var values=new List<BalanceProfile.Parameter>();var property=new SerializedObject(component).GetIterator();
                while(property.Next(true))
                {
                    string field=property.propertyPath.Split('.')[0];
                    if(field.StartsWith("m_",StringComparison.Ordinal)||excluded.Contains(field)||property.propertyPath.Contains(".m_")||property.propertyPath.Contains("m_Bits")||property.propertyPath.Contains("frameBounds"))continue;
                    if(property.propertyPath.Contains(".sprites.")||property.propertyPath.Contains(".Array.size"))continue;
                    bool isFloat=property.propertyType==SerializedPropertyType.Float,isInt=property.propertyType==SerializedPropertyType.Integer,isBool=property.propertyType==SerializedPropertyType.Boolean;
                    if(!isFloat&&!isInt&&!isBool)continue;
                    if(!ValidParameter(component.GetType().FullName,property.propertyPath))continue;
                    // Only fields explicitly authored as data; public runtime counters are not tuning inputs.
                    System.Reflection.FieldInfo f=null;
                    for(Type t=component.GetType();t!=null&&f==null;t=t.BaseType)f=t.GetField(field,System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.DeclaredOnly);
                    if(f==null||!Attribute.IsDefined(f,typeof(SerializeField))&&component is not AttackBox)continue;
                    double v=isFloat?property.doubleValue:isInt?property.intValue:property.boolValue?1:0;
                    values.Add(new BalanceProfile.Parameter{path=property.propertyPath,label=Label(property.propertyPath),value=v,integer=isInt,boolean=isBool});
                }
                if(values.Count==0)continue;
                settings.Add(new BalanceProfile.ComponentSettings{objectPath=AnimationUtility.CalculateTransformPath(component.transform,prefab.transform),componentType=component.GetType().FullName,componentIndex=Array.IndexOf(component.GetComponents(component.GetType()),component),parameters=values.ToArray()});
                if(!routes.ContainsKey(component.GetType().FullName))routes[component.GetType().FullName]=route;
            }
            if(asset.components.Length==0){asset.components=settings.ToArray();EditorUtility.SetDirty(asset);}
            var existing=asset.components.ToList();
            foreach(var source in settings)
            {
                var destination=existing.FirstOrDefault(g=>g.componentType==source.componentType&&g.componentIndex==source.componentIndex&&g.objectPath==source.objectPath);
                if(destination==null){existing.Add(source);continue;}
                var keys=new HashSet<string>(destination.parameters.Select(p=>p.path));destination.parameters=destination.parameters.Concat(source.parameters.Where(p=>!keys.Contains(p.path))).ToArray();
            }
            foreach(var physics in prefab.GetComponentsInChildren<Component>(true).Where(c=>c is Rigidbody2D))//只导出刚体手感数值；碰撞箱尺寸由预制体控制
            {
                string relative=AnimationUtility.CalculateTransformPath(physics.transform,prefab.transform);
                if(existing.Any(g=>g.componentType==physics.GetType().FullName&&g.objectPath==relative))continue;
                string[] properties={"m_Mass","m_GravityScale","m_LinearDamping"};
                var so=new SerializedObject(physics);var values=new List<BalanceProfile.Parameter>();
                foreach(string name in properties){var property=so.FindProperty(name);if(property!=null)values.Add(new BalanceProfile.Parameter{path=name,label=(name.Contains("Gravity")?"重力倍率":name.Contains("Mass")?"质量":"水平阻尼")+" · "+name,value=property.doubleValue});}
                existing.Add(new BalanceProfile.ComponentSettings{objectPath=relative,componentType=physics.GetType().FullName,componentIndex=Array.IndexOf(physics.GetComponents(physics.GetType()),physics),parameters=values.ToArray()});
            }
            asset.components=existing.ToArray();EditorUtility.SetDirty(asset);
            var binding=prefab.GetComponent<BalanceBinding>();if(binding==null)binding=prefab.AddComponent<BalanceBinding>();
            var serialized=new SerializedObject(binding);serialized.FindProperty("profile").objectReferenceValue=asset;serialized.ApplyModifiedPropertiesWithoutUndo();
            PrefabUtility.SaveAsPrefabAsset(prefab,path);
        }
        finally{PrefabUtility.UnloadPrefabContents(prefab);}
    }
}
